using Fylkren.Api.DomainEvents;
using Microsoft.EntityFrameworkCore;

namespace Fylkren.Api.Persistence;

internal static class DomainEventModelConfiguration
{
    internal static void ConfigureDomainEvents(this ModelBuilder modelBuilder)
    {
        var e = modelBuilder.Entity<DomainEvent>(); e.ToTable("domain_events"); e.HasKey(x => x.Id);
        e.Property(x => x.Id).HasColumnName("id"); e.Property(x => x.EventType).HasColumnName("event_type").HasMaxLength(100); e.Property(x => x.SchemaVersion).HasColumnName("schema_version"); e.Property(x => x.OccurredAt).HasColumnName("occurred_at"); e.Property(x => x.SiteId).HasColumnName("site_id"); e.Property(x => x.ActorPersonId).HasColumnName("actor_person_id"); e.Property(x => x.ResourceType).HasColumnName("resource_type").HasMaxLength(80); e.Property(x => x.ResourceId).HasColumnName("resource_id"); e.Property(x => x.PayloadJson).HasColumnName("payload_json").HasColumnType("jsonb"); e.Property(x => x.WebhooksProjectedAt).HasColumnName("webhooks_projected_at"); e.HasIndex(x => new { x.SiteId, x.OccurredAt }); e.HasIndex(x => new { x.EventType, x.OccurredAt }); e.HasIndex(x => x.WebhooksProjectedAt);
        var s = modelBuilder.Entity<WebhookSubscription>(); s.ToTable("webhook_subscriptions"); s.HasKey(x => x.Id);
        s.Property(x => x.Id).HasColumnName("id"); s.Property(x => x.SiteId).HasColumnName("site_id"); s.Property(x => x.Name).HasColumnName("name").HasMaxLength(120); s.Property(x => x.EndpointUrl).HasColumnName("endpoint_url").HasMaxLength(2000); s.Property(x => x.ProtectedSecret).HasColumnName("protected_secret").HasMaxLength(2000); s.Property(x => x.EventTypes).HasColumnName("event_types").HasMaxLength(1000); s.Property(x => x.CreatedByPersonId).HasColumnName("created_by_person_id"); s.Property(x => x.CreatedAt).HasColumnName("created_at"); s.Property(x => x.UpdatedAt).HasColumnName("updated_at"); s.Property(x => x.IsActive).HasColumnName("is_active"); s.HasIndex(x => new { x.SiteId, x.IsActive });
        var d = modelBuilder.Entity<WebhookDelivery>(); d.ToTable("webhook_deliveries"); d.HasKey(x => x.Id);
        d.Property(x => x.Id).HasColumnName("id"); d.Property(x => x.SubscriptionId).HasColumnName("subscription_id"); d.Property(x => x.DomainEventId).HasColumnName("domain_event_id"); d.Property(x => x.Status).HasColumnName("status").HasMaxLength(30); d.Property(x => x.AttemptCount).HasColumnName("attempt_count"); d.Property(x => x.NextAttemptAt).HasColumnName("next_attempt_at"); d.Property(x => x.LastAttemptAt).HasColumnName("last_attempt_at"); d.Property(x => x.CompletedAt).HasColumnName("completed_at"); d.Property(x => x.LastHttpStatus).HasColumnName("last_http_status"); d.Property(x => x.LastError).HasColumnName("last_error").HasMaxLength(1000); d.Property(x => x.CreatedAt).HasColumnName("created_at"); d.HasOne(x => x.Subscription).WithMany().HasForeignKey(x => x.SubscriptionId).OnDelete(DeleteBehavior.Restrict); d.HasOne(x => x.DomainEvent).WithMany().HasForeignKey(x => x.DomainEventId).OnDelete(DeleteBehavior.Restrict); d.HasIndex(x => new { x.SubscriptionId, x.DomainEventId }).IsUnique(); d.HasIndex(x => new { x.Status, x.NextAttemptAt });
        var a = modelBuilder.Entity<WebhookDeliveryAttempt>(); a.ToTable("webhook_delivery_attempts"); a.HasKey(x => x.Id);
        a.Property(x => x.Id).HasColumnName("id"); a.Property(x => x.DeliveryId).HasColumnName("delivery_id"); a.Property(x => x.AttemptNumber).HasColumnName("attempt_number"); a.Property(x => x.AttemptedAt).HasColumnName("attempted_at"); a.Property(x => x.DurationMs).HasColumnName("duration_ms"); a.Property(x => x.Outcome).HasColumnName("outcome").HasMaxLength(30); a.Property(x => x.HttpStatus).HasColumnName("http_status"); a.Property(x => x.Error).HasColumnName("error").HasMaxLength(1000); a.HasOne(x => x.Delivery).WithMany().HasForeignKey(x => x.DeliveryId).OnDelete(DeleteBehavior.Cascade); a.HasIndex(x => new { x.DeliveryId, x.AttemptNumber }).IsUnique();
    }
}
